python3 << 'EOF'
import json
import subprocess

# Test nested branch with over-long field
test = {
    "pipeline": {"steps": [
        {"op": "branch", "branches": [
            {"when": "id > 5", "steps": [
                {"op": "select", "columns": ["id", "a"*65]}
            ]}
        ]}
    ]},
    "dataset": []
}

result = subprocess.run(["python", "etl_pipeline.py"],
                       input=json.dumps(test),
                       capture_output=True, text=True)
output = json.loads(result.stdout)

expected_path = "pipeline.steps[0].branches[0].steps[0].columns[1]"
if output.get('path') == expected_path:
    print(f"✓ Nested branch path correct: {output.get('path')}")
else:
    print(f"✗ Nested branch path incorrect. Expected: {expected_path}, Got: {output.get('path')}")
EOF

